def _compile_paging(
    self, node: FieldNode, field, target: TypeInfo
) -> Dict[str, Any]:
    """Validate and resolve the four paging arguments of a list root.

    The arguments are only recognized when the schema field itself
    declares them; otherwise they keep failing as unknown arguments in the
    caller. Static literals that violate the contract fail with
    InvalidQuery; variable-provided failures surface as VariablesError.
    """
    def declared(arg_name: str) -> bool:
        return _is_paging_field(field, arg_name)

    page_raw = node.args.get("page")
    size_raw = node.args.get("pageSize")
    order_raw = node.args.get("orderBy")
    direction_raw = node.args.get("sortDirection")

    page_present = page_raw is not None or "page" in node.args
    size_present = size_raw is not None or "pageSize" in node.args
    # Explicit null counts as supplied: the declared argument type decides
    # whether that is legal, and page without a usable pageSize still ends
    # with InvalidQuery.
    page_present = "page" in node.args
    size_present = "pageSize" in node.args
    order_present = "orderBy" in node.args and node.args["orderBy"] is not None
    direction_present = (
        "sortDirection" in node.args
        and node.args["sortDirection"] is not None
    )

    page = 0
    if page_present:
        page = self._resolve_paging_int(
            "page", page_raw, allow_zero=True
        )
    page_size = None
    if size_present:
        page_size = self._resolve_paging_int(
            "pageSize", size_raw, allow_zero=False
        )
    order_by = None
    if order_present:
        order_by = self._resolve_order_by(order_raw, target)
    sort_direction = "ASC"
    if direction_present:
        sort_direction = self._resolve_sort_direction(direction_raw)

    if page_present and not size_present:
        raise PlanError(
            "InvalidQuery",
            f"argument 'page' on root field '{node.name}' requires 'pageSize'",
        )
    if size_present and page_size is None:
        raise PlanError(
            "InvalidQuery",
            f"argument 'pageSize' on root field '{node.name}' must be a "
            f"positive integer",
        )
    if page_present and page is None:
        raise PlanError(
            "InvalidQuery",
            f"argument 'page' on root field '{node.name}' must be a "
            f"non-negative integer",
        )
    if direction_present and order_by is None:
        raise PlanError(
            "InvalidQuery",
            f"argument 'sortDirection' on root field '{node.name}' "
            f"requires 'orderBy'",
        )
