def _resolve_paging_int(
    self, arg_name: str, value: Any, allow_zero: bool
) -> Optional[int]:
    """Resolve page/pageSize to an int, or None when the value is invalid.

    Literal problems (non-integer literal, wrong sign) are reported here as
    InvalidQuery; variable problems are VariablesError. None is returned
    for a resolved-but-illegal value so the caller can emit one common
    diagnostic; an explicit null on a non-null declared argument is caught
    by the variable type check and reported as VariablesError.
    """
    if isinstance(value, Var):
        resolved = self._resolve(value)
        if isinstance(resolved, bool) or not isinstance(resolved, int):
            raise PlanError(
                "VariablesError",
                f"variable '${value.name}' used for '{arg_name}' must be "
                f"an integer",
            )
        if resolved < 0 or (not allow_zero and resolved == 0):
            raise PlanError(
                "VariablesError",
                f"variable '${value.name}' used for '{arg_name}' has an "
                f"invalid value {resolved}",
            )
        return resolved
    if isinstance(value, bool) or not isinstance(value, int):
        raise PlanError(
            "InvalidQuery",
            f"argument '{arg_name}' must be an integer literal",
        )
    if value < 0 or (not allow_zero and value == 0):
        raise PlanError(
            "InvalidQuery",
            f"argument '{arg_name}' has an invalid value {value}",
        )
    return value

def _resolve_order_by(self, value: Any, target: TypeInfo) -> Optional[str]:
    """Resolve orderBy to a sortable root-entity field name."""
    if isinstance(value, Var):
        resolved = self._resolve(value)
        if not isinstance(resolved, str) or isinstance(resolved, EnumLiteral):
            raise PlanError(
                "VariablesError",
                f"variable '${value.name}' used for 'orderBy' must be a string",
            )
        self._check_order_field(resolved, target, variable=True,
                                var_name=value.name)
        return resolved
    if isinstance(value, EnumLiteral):
        # Enum literals are unquoted names; the schema argument is a
        # String, so a static enum is a statically invalid value.
        self._check_order_field(str(value), target, variable=False)
        return str(value)
    if not isinstance(value, str):
        raise PlanError(
            "InvalidQuery",
            "argument 'orderBy' must be a field name string",
        )
    self._check_order_field(value, target, variable=False)
    return value

def _check_order_field(
    self,
    name: str,
    target: TypeInfo,
    variable: bool,
    var_name: Optional[str] = None,
) -> None:
    """Reject orderBy targets that are unknown, nullable, list or composite."""
    order_field = target.fields.get(name)
    code = "VariablesError" if variable else "InvalidQuery"
    if order_field is None:
        raise PlanError(
            code,
            f"orderBy field '{name}' is not a field of type '{target.name}'",
        )
    if _is_list_type(order_field.type_ref):
        raise PlanError(
            code,
            f"orderBy field '{name}' must not be a list field",
        )
    if order_field.type_ref[0] != "non_null":
        raise PlanError(
            code,
            f"orderBy field '{name}' must be non-null",
        )
    named = named_of(order_field.type_ref)
    if (
        named not in ("Int", "Float", "String", "ID", "Boolean")
        and named not in self.schema.enums
    ):
        raise PlanError(
            code,
            f"orderBy field '{name}' must be a scalar or enum field",
        )

def _resolve_sort_direction(self, value: Any) -> str:
    if isinstance(value, Var):
        resolved = self._resolve(value)
        if not isinstance(resolved, str) or isinstance(resolved, EnumLiteral):
            raise PlanError(
                "VariablesError",
                f"variable '${value.name}' used for 'sortDirection' must "
                f"be ASC or DESC",
            )
        if resolved not in SORT_DIRECTIONS:
            raise PlanError(
                "VariablesError",
                f"variable '${value.name}' used for 'sortDirection' must "
                f"be ASC or DESC",
            )
        return resolved
    if isinstance(value, EnumLiteral):
        if value not in SORT_DIRECTIONS:
            raise PlanError(
                "InvalidQuery",
                f"argument 'sortDirection' must be ASC or DESC",
            )
        return str(value)
    raise PlanError(
        "InvalidQuery",
        "argument 'sortDirection' must be the enum literal ASC or DESC",
    )

